// Function to seed 369 shapes
export async function seed369Shapes(): Promise<{ success: boolean; count: number; error?: string }> {
  if (!connectionString) {
    console.log('⚠️ DATABASE_URL not configured - skipping 369 shapes seeding');
    return { success: false, count: 0, error: 'No database connection' };
  }

  const sql = neon(connectionString);
  const db = drizzle(sql);

  try {
    console.log('\n🔮 Starting 369 Sacred Shape Seeding...');
    console.log('📊 Tesla\'s Divine Number: 3, 6, 9 - The Keys to the Universe\n');

    let seededCount = 0;

    for (const shape of SACRED_369_SHAPES) {
      try {
        // Check if shape already exists
        const existing = await db.select().from(formula_implementations)
          .where(eq(formula_implementations.shape_type, shape.shape_type))
          .limit(1);

        if (existing.length > 0) {
          console.log(`  ⏭️  ${shape.shape_type} already exists`);
          continue;
        }

        // Insert new shape with all required fields
        await db.insert(formula_implementations).values({
          shape_type: shape.shape_type,
          formula_name: shape.formula_name,
          equation_function: `(u, v, params) => { const a = params.a ?? 1; return { x: a*cos(u)*sin(v), y: a*sin(u)*sin(v), z: a*cos(v) }; }`,
          category: shape.category,
          subcategory: shape.subcategory,
          implementation_notes: shape.description,
          equation_x_formula: shape.formula_display,
          equation_y_formula: shape.formula_display,
          equation_z_formula: shape.formula_display,
          parameter_dependencies: JSON.stringify(['a', 'b', 'c']),
          default_parameters: JSON.stringify({ a: 1, b: 1, c: 1, d: 0, e: 0, f: 0, g: 0, h: 0, i: 0, j: 0, k: 0, l: 0, m: 0 }),
          uv_domain: JSON.stringify({ uMin: -Math.PI, uMax: Math.PI, vMin: -Math.PI, vMax: Math.PI }),
          segment_settings: JSON.stringify({ uSegments: 64, vSegments: 64 }),
          complexity_score: shape.complexity_score,
          symbolic_classification: shape.seo_keywords.join(', '),
          mathematical_foundation: shape.description,
          is_verified: true,
          security_level: 'public',
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString()
        });

        seededCount++;
        console.log(`  ✅ Seeded: ${shape.formula_name} [${shape.category}]`);
      } catch (err) {
        console.log(`  ⚠️ Failed to seed ${shape.shape_type}: ${err}`);
      }
    }

    console.log(`\n🎯 369 Sacred Shape Seeding Complete!`);
    console.log(`📊 Total shapes seeded: ${seededCount}`);
    console.log(`📂 Categories covered: 12`);

    return { success: true, count: seededCount };
  } catch (error) {
    console.error('❌ Failed to seed 369 shapes:', error);
    return { success: false, count: 0, error: String(error) };
  }
}

// Run if called directly
if (import.meta.url.endsWith(process.argv[1])) {
  seed369Shapes().then(result => {
    console.log('\n📊 Final Result:', result);
    process.exit(result.success ? 0 : 1);
  });
}